CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,content TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),title_en TEXT,content_en TEXT,seed_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT NOT NULL,category TEXT NOT NULL,brand TEXT DEFAULT '',model TEXT DEFAULT '',condition_text TEXT DEFAULT '',condition_en TEXT DEFAULT '',description TEXT DEFAULT '',description_en TEXT DEFAULT '',dimensions TEXT DEFAULT '',dimensions_en TEXT DEFAULT '',price NUMERIC(12,2),image_url TEXT,image_extra_url TEXT DEFAULT '',is_example INTEGER DEFAULT 1,verified INTEGER DEFAULT 0,published INTEGER DEFAULT 0,featured INTEGER DEFAULT 0,seed_key TEXT UNIQUE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());